diffs.replacement:
@charset "UTF-8";

/* RETRO PALETTE - REFINED */
.light {
  --background: #F0F2F5; /* Softer Gray */
  --surface: #FFFFFF;
  --text: #1A1A1A;
  --border: #2D2D2D;
  --highlight: #FFFFFF;
  --primary: #5C6BC0; /* Retro Blue */
  --secondary: #FF7043; /* Retro Orange */
  --accent: #66BB6A; /* Retro Green */
  --track: #BDBDBD;
  --link: #1565C0;
  --tooltip-bg: #2D2D2D;
  --tooltip-text: #FFFFFF;
  --active-item-bg: #E8EAF6;
  --shadow-color: rgba(0, 0, 0, 0.2);
}

.dark {
  --background: #121212; /* Deep Dark */
  --surface: #1E1E1E;
  --text: #E0E0E0;
  --border: #4A4A4A;
  --highlight: #2C2C2C;
  --primary: #7986CB;
  --secondary: #FF8A65;
  --accent: #81C784;
  --track: #424242;
  --link: #64B5F6;
  --tooltip-bg: #E0E0E0;
  --tooltip-text: #121212;
  --active-item-bg: #283593;
  --shadow-color: rgba(0, 0, 0, 0.5);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-variant-ligatures: none;
}

:root {
  --track-fill: #fff;
  --mid: #757575;
  /* Retro Fonts */
  --font-body: "VT323", monospace;
  --font-header: "Press Start 2P", cursive;

  /* Modern Retro Constants */
  --radius: 6px; /* Softens the blockiness */
  --border-width: 2px; /* Lighter borders */
}

html, body {
  height: 100%;
  font-family: var(--font-body);
  font-size: 18px; 
  background-color: var(--background);
  color: var(--text);
}

#root {
  width: 100%;
  height: 100%;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-header);
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 0px;
  line-height: 1.4;
  font-size: 14px; /* Reduced for better sizing */
}

li {
  list-style: none;
}

/* MODERN RETRO INPUTS */
input, textarea {
  font-family: var(--font-body);
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  outline: none;
  font-size: 20px;
  resize: none;
  user-select: text;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.15s ease;
}

input::placeholder, textarea::placeholder {
  user-select: none;
  opacity: 0.5;
}

textarea {
  width: 100%;
  background: var(--highlight);
  padding: 12px;
  margin-bottom: 15px;
}

textarea:focus, input:focus {
  border-color: var(--primary);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
}

[role=button] {
  cursor: pointer;
}

/* MODERN RETRO BUTTONS */
button {
  font-family: var(--font-body); /* Switch to body font for cleaner UI */
  font-size: 20px; /* Readable size */
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--surface);
  color: var(--text);
  border: var(--border-width) solid var(--border);
  cursor: pointer;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0px 0px var(--shadow-color);
  transition: all 0.1s;
  padding: 6px 12px;
}

button:hover:not([disabled]) {
  transform: translateY(-1px);
  box-shadow: 3px 3px 0px 0px var(--shadow-color);
  background: var(--highlight);
}

button:active:not([disabled]) {
  transform: translateY(1px);
  box-shadow: 1px 1px 0px 0px var(--shadow-color);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  box-shadow: none;
  background: var(--track);
  border-color: transparent;
}

button .icon {
  display: block;
}

.button {
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.button.inactive {
  opacity: 0.3;
  pointer-events: none;
}

/* ICONS */
.icon {
  font-family: "Material Symbols Outlined";
  font-weight: normal;
  line-height: 1;
  font-size: 22px;
}

/* MAIN LAYOUT */
main {
  width: 100%;
  height: 100%;
  display: flex;
  background: var(--background);
  color: var(--text);
}

.contentWrapper {
  max-width: 1400px;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  margin: 0 auto;
  overflow: hidden;
  background: var(--background);
}

.top {
  display: flex;
  height: 50%; 
  border-bottom: var(--border-width) solid var(--border);
  background: var(--surface);
}

.tools {
  display: flex;
  gap: 20px;
  flex: 1;
  overflow: hidden;
  transition: opacity 0.2s;
  background-color: var(--surface);
}
.tools.inactive {
  opacity: 0.5;
  pointer-events: none;
  filter: grayscale(100%);
}

.collapseButton {
  border: none;
  border-left: var(--border-width) solid var(--border);
  width: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--surface);
  color: var(--text);
  box-shadow: none;
  border-radius: 0;
}
.collapseButton:hover {
    background: var(--active-item-bg);
}

.modeSelector {
  display: flex;
  flex-direction: column;
  gap: 0; 
  overflow: hidden;
  transition: width 0.3s ease;
  position: relative;
  flex-shrink: 0;
  padding-right: 4px; 
  background-color: var(--surface);
}
.modeSelector.resizing {
  transition: none;
  user-select: none;
}
.modeSelector.hide {
  width: 0;
  padding-right: 0;
}

.sidebarContent {
  padding: 20px 15px;
  padding-bottom: 100px; /* Extra space for floating footer */
  min-width: 220px;
  flex: 1 1 auto; 
  overflow-y: auto;
  min-height: 0; 
  /* Push content to bottom */
  display: flex;
  flex-direction: column;
}

/* Custom Scrollbar - Cleaner */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--track);
  border-radius: 5px;
  border: 2px solid var(--surface);
}
::-webkit-scrollbar-thumb:hover {
    background: var(--mid);
}

/* FLOATING FOOTER - Modern Retro */
.sidebarFooter {
  padding: 15px;
  min-width: 220px;
  flex-shrink: 0;
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  background: linear-gradient(to bottom, transparent 0%, var(--surface) 40%);
  border-top: none;
  pointer-events: none;
  z-index: 10;
  padding-bottom: 20px;
}

.sidebarFooter button {
  pointer-events: auto;
  background: var(--accent); 
  color: #000; /* Contrast text */
  border: var(--border-width) solid var(--border);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1), 2px 2px 0 var(--border);
  font-weight: bold;
}
.sidebarFooter button:hover:not([disabled]) {
    transform: translateY(-2px);
    box-shadow: 0 6px 8px rgba(0,0,0,0.15), 2px 2px 0 var(--border);
}
.sidebarFooter .navBack {
  background: var(--surface);
  color: var(--text);
}

.modeSelector h2 {
  font-size: 12px;
  color: var(--mid);
  margin-bottom: 12px;
  font-family: var(--font-header);
}

.resizer {
  position: absolute;
  top: 0;
  right: 0;
  width: 6px;
  height: 100%;
  cursor: col-resize;
  z-index: 100;
  transition: background-color 0.2s;
  background: transparent;
}
.resizer:hover, .modeSelector.resizing .resizer {
  background-color: var(--primary);
  opacity: 0.5;
}

.modeList {
  flex-direction: column;
  display: flex;
  gap: 8px;
}
.modeList .button {
  justify-content: flex-start;
  gap: 12px;
  background: transparent;
  color: var(--text);
  white-space: nowrap;
  border: 1px solid transparent;
  min-width: fit-content;
  width: 100%;
  position: relative;
  font-size: 20px;
  box-shadow: none;
  border-radius: var(--radius);
  padding: 10px;
}
.modeList .button:not([disabled]):hover {
  background: var(--active-item-bg);
  border-color: var(--track);
  box-shadow: none;
  transform: none;
}
.modeList .button.active {
  background: var(--primary);
  color: #FFF;
  border-color: var(--border);
  box-shadow: 2px 2px 0 var(--shadow-color);
}
.modeList .button .emoji {
    font-size: 20px;
}

.modeList .tooltip {
  visibility: hidden;
  width: 220px;
  background-color: var(--tooltip-bg);
  color: var(--tooltip-text);
  text-align: center;
  border: var(--border-width) solid var(--border);
  padding: 10px;
  position: absolute;
  z-index: 10;
  bottom: 125%;
  left: 50%;
  margin-left: -110px;
  opacity: 0;
  transition: opacity 0.2s;
  font-size: 16px;
  line-height: 1.3;
  white-space: normal;
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.modeList .button:hover .tooltip {
  visibility: visible;
  opacity: 1;
}

.generateButton {
  padding: 14px 20px;
  width: 100%;
  font-size: 18px;
  font-family: var(--font-header);
}

.output {
  flex: 1;
  padding: 25px 30px;
  overflow: auto;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 20px;
  background-color: var(--surface);
  /* Subtle dot pattern for texture */
  background-image: radial-gradient(var(--track) 1px, transparent 1px);
  background-size: 20px 20px;
}
.output:hover .sentence {
  opacity: 0.7;
}
.output time {
  color: var(--link);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.9em;
  text-decoration: none;
  background: rgba(0,0,0,0.05);
  font-family: var(--font-body);
  border: 1px solid rgba(0,0,0,0.1);
}
.output .sentence {
  font-size: 22px; 
  line-height: 1.6;
  display: inline;
  cursor: pointer;
  transition: all 0.1s;
  border: 1px solid transparent;
  padding: 4px 6px;
  text-align: left;
  color: inherit;
  font-family: inherit;
  background: transparent;
  border-radius: 6px;
  margin: 0 2px;
}
.output .sentence:hover {
  opacity: 1;
  background-color: var(--active-item-bg);
}
.output .sentence.activeSentence {
  opacity: 1;
  background-color: var(--highlight);
  border: var(--border-width) solid var(--primary);
  box-shadow: 2px 2px 0 var(--shadow-color);
}
.output .sentence time {
  margin-right: 10px;
}
.output ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.output ul button {
  font-size: 20px;
  display: flex;
  gap: 15px;
  text-align: left;
  padding: 16px;
  border-radius: var(--radius);
  width: 100%;
  background: var(--highlight);
  border: 1px solid var(--track);
  box-shadow: 2px 2px 0 var(--shadow-color);
  transition: all 0.1s;
}
.output ul button:hover {
  transform: translateY(-2px);
  box-shadow: 3px 3px 0 var(--shadow-color);
  border-color: var(--primary);
}
.output ul button.activeItem {
  background: var(--active-item-bg);
  border: 2px solid var(--primary);
  box-shadow: inset 0 0 0 1px var(--primary);
}
.output ul button p {
  font-size: 20px;
}

.output .apiError {
  color: #FFF;
  background-color: #EF5350;
  padding: 20px;
  border-radius: var(--radius);
  border: var(--border-width) solid #C62828;
  box-shadow: 4px 4px 0 rgba(198, 40, 40, 0.4);
  font-family: var(--font-body);
  font-size: 18px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.output .textResponse {
  white-space: pre-wrap;
  line-height: 1.6;
  font-size: 20px;
}

.modeEmojis .sentence {
  font-size: 40px;
  margin-right: 20px;
}
.modeEmojis .sentence time {
  top: -8px;
}

.modeHaiku .sentence {
  display: block;
  font-size: 24px;
  margin-bottom: 15px;
  border-left: 4px solid var(--accent);
  padding-left: 15px;
  background: var(--highlight);
  padding: 15px;
  border-radius: var(--radius);
  box-shadow: 2px 2px 0 var(--shadow-color);
}

.modeTable table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 3px 3px 0 var(--shadow-color);
  background: var(--highlight);
}
.modeTable th {
  text-align: left;
  background: var(--background);
  color: var(--text);
  font-family: var(--font-header);
  font-size: 12px;
  padding: 15px;
  border-bottom: var(--border-width) solid var(--border);
  border-right: 1px solid var(--track);
}
.modeTable th:last-child {
    border-right: none;
}
.modeTable td {
  padding: 15px;
  border-bottom: 1px solid var(--track);
  border-right: 1px solid var(--track);
}
.modeTable td:last-child {
    border-right: none;
}
.modeTable tr:last-child td {
    border-bottom: none;
}
.modeTable tr.activeRow td {
  background-color: var(--active-item-bg);
}

.loading {
  display: flex;
  align-items: center;
  gap: 20px;
  font-family: var(--font-body);
  font-size: 20px;
  padding: 30px;
  background: var(--highlight);
  border: var(--border-width) solid var(--border);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
  justify-content: center;
}

/* Spinner - Less glitchy, more smooth retro */
.spinner {
  width: 24px;
  height: 24px;
  border: 4px solid var(--track);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

.cancelButton {
  border: var(--border-width) solid var(--border);
  padding: 6px 12px;
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  font-size: 16px;
}
.cancelButton:hover {
    background: var(--background);
}

.lineChart {
  width: 100%;
  height: 100%;
  min-height: 300px;
  border: var(--border-width) solid var(--border);
  background: var(--highlight);
  box-shadow: 4px 4px 0 var(--shadow-color);
  border-radius: var(--radius);
  padding: 10px;
}
.lineChart path {
  fill: none;
  stroke: var(--primary);
  stroke-width: 3px; 
  stroke-linecap: round; 
  stroke-linejoin: round;
}
.lineChart circle {
  fill: var(--surface);
  stroke: var(--secondary);
  stroke-width: 2px;
}

.axisLabels text {
  text-anchor: middle;
  font-size: 16px;
  fill: var(--text);
  font-family: var(--font-body);
}

.axisTitle {
  font-size: 14px;
  fill: var(--text);
  font-family: var(--font-header);
}

.dataPoint text {
  fill: var(--text);
  font-size: 14px;
  text-anchor: middle;
  font-family: var(--font-body);
}

.timeLabels text {
  cursor: pointer;
  fill: var(--link);
  text-decoration: none;
  font-weight: bold;
}
.timeLabels text:hover {
    fill: var(--secondary);
    text-decoration: underline;
}

video {
  width: 100%;
  height: 100%;
  max-height: calc(50vh - 54px);
  margin: 0 auto;
}

.videoPlayer {
  flex: 1;
  background: #111;
  display: flex;
  align-items: stretch;
  flex-direction: column;
  justify-content: center;
  font-size: 0;
  position: relative;
  user-select: none;
  border-left: var(--border-width) solid var(--border);

  /* Modern Monitor Look - Cleaner than CRT */
  border: 4px solid #222;
  border-radius: 8px;
  box-shadow: 0 4px 10px rgba(0,0,0,0.3);
}

.videoPlayer:fullscreen {
  max-height: 100vh;
  border: none;
  border-radius: 0;
}


.videoPlayer:has(.timecodeMarker:hover) .videoCaption {
  opacity: 0;
}
.mediaContainer {
  display: flex;
  flex: 1;
  position: relative;
  min-height: 200px;
  overflow: hidden;
  border-radius: 4px 4px 0 0;
}

.audioPlaceholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
  pointer-events: none;
  background: radial-gradient(circle, #333 0%, #111 100%);
}
.audioPlaceholder .icon {
    font-size: 80px;
    color: var(--primary);
    opacity: 0.5;
}

.emptyVideo {
  min-height: 50vh;
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  width: 100%;
  font-family: var(--font-body);
}
.uploadLabel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  cursor: pointer;
  width: 100%;
  height: auto;
  flex: 0;
  padding: 20px;
  margin-bottom: 20px;
}
.emptyVideo .icon {
  font-size: 64px;
  color: var(--secondary);
  margin-bottom: 10px;
}

.emptyVideo p {
  max-width: 500px;
  text-align: center;
  line-height: 1.5;
}
.emptyVideo p.error {
    color: #FFF;
    background-color: #EF5350;
    padding: 15px 25px;
    border-radius: var(--radius);
    box-shadow: 0 4px 8px rgba(0,0,0,0.2);
}

.uploadProgress {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
  width: 100%;
  max-width: 300px;
  color: #fff;
  cursor: default;
  padding: 30px;
  border: var(--border-width) solid var(--border);
  background: var(--surface);
  color: var(--text);
  border-radius: var(--radius);
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.progressBar {
  width: 100%;
  height: 12px;
  background-color: var(--track);
  border-radius: 6px;
  overflow: hidden;
}

.progressFill {
  width: 0%;
  height: 100%;
  background-color: var(--accent);
  transition: width 0.3s ease;
  border-radius: 6px;
}

.videoCaption {
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(4px);
  position: absolute;
  bottom: 80px;
  text-align: center;
  padding: 12px 20px;
  color: #FFF;
  max-width: 720px;
  font-size: 22px;
  margin-inline: 30px;
  left: 50%;
  translate: -50% 0;
  width: -webkit-fill-available;
  border-radius: 8px;
  transition: opacity 0.2s;
  z-index: 2;
  font-family: var(--font-body);
  text-shadow: 1px 1px 0 #000;
  border: 1px solid rgba(255,255,255,0.2);
}

.videoControls {
  font-size: 12px;
  position: relative;
  background: #222; /* Darker controls */
  z-index: 3;
  color: #FFF;
  border-radius: 0 0 4px 4px;
}

/* Modern Retro Scrubber */
.videoScrubber {
  height: 12px; 
  transform-origin: bottom;
  transition: none;
  overflow: hidden;
  background: #333;
  cursor: pointer;
}
.videoScrubber:hover {
    height: 16px;
}
.videoScrubber input {
  position: relative;
  top: -6px;
  height: 20px;
  appearance: none;
  width: 100%;
  background: transparent;
  border: none;
  box-shadow: none;
  border-radius: 0;
}
/* Custom range track for retro look */
.videoScrubber input::-webkit-slider-runnable-track {
    background: linear-gradient(to right, var(--primary) 0%, var(--primary) var(--pct), #555 var(--pct), #555 100%);
    height: 100%;
}
.videoScrubber input::-webkit-slider-thumb {
  opacity: 0;
}

.videoTime {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px;
  font-size: 16px;
  border-top: 1px solid #333;
  gap: 20px;
  background: #222;
  font-family: var(--font-header);
}
.videoTime button {
  background: transparent;
  border: none;
  box-shadow: none;
  color: #AAA;
  padding: 0;
  transition: color 0.1s;
}
.videoTime button:hover {
    color: #FFF;
    transform: none;
    background: transparent;
}
.videoTime .timeDisplay {
  flex-shrink: 0;
  font-family: var(--font-body);
  font-size: 20px;
  color: #DDD;
}

.volumeControls {
    display: flex;
    align-items: center;
    gap: 15px;
    flex: 1;
}

.volumeSlider {
    width: 100%;
    max-width: 120px;
    height: 6px;
    accent-color: var(--primary);
    background: #444;
    border: none;
    box-shadow: none;
    border-radius: 3px;
}


.timecodeList {
  overflow: auto;
  padding: 10px 20px;
}
.timecodeList td {
  padding: 10px 5px;
}
.timecodeList button {
  color: var(--link);
  box-shadow: none;
  border: none;
  background: transparent;
}
.timecodeList button:hover {
  color: var(--secondary);
  text-decoration: underline;
}

.timecodeMarkers {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.timecodeMarker {
  position: absolute;
  top: 0;
  width: 2px;
  background: rgba(255, 255, 255, 0.5); 
  translate: -1px 0;
  z-index: 4;
}
.timecodeMarker:hover {
    width: 4px;
    background: var(--accent);
    translate: -2px 0;
    z-index: 5;
}
.timecodeMarker:hover .timecodeMarkerLabel {
  opacity: 1;
}

.timecodeMarkerTick {
  height: 12px;
  pointer-events: auto;
  cursor: pointer;
  background: transparent;
}

.timecodeMarkerLabel {
  background: #222;
  border: 1px solid #555;
  box-shadow: 0 4px 8px rgba(0,0,0,0.5);
